 Here is a simple example of a LaTeX code using TikZ and pgfplots to create the desired 2D plot. I have defined professional-looking colors and styles for the plot.

```latex
\documentclass{article}
\usepackage{tikz}
\usepackage{pgfplots}
\usetikzlibrary{patterns}

\begin{document}

\begin{tikzpicture}
    \begin{axis}[
        xlabel={$x$},
        ylabel={$y$},
        xmin=-1, xmax=5,
        ymin=-1, ymax=5,
        axis lines=middle,
        xmajorgrids,
        ymajorgrids,
        grid style={gray!30},
        axis line style={latex-latex},
        tick label style={font=\scriptsize},
        enlargelimits=false,
        clip=false,
        colormap/blackwhite,
        ]

    \addplot [
        mark=*,
        only marks,
        mark options={scale=1.5, fill=black},
        ] coordinates {
            (1, 2) coordinate (x), % x point
            (2, 4) coordinate (y1), % y1 point
            (3, 3) coordinate (y2), % y2 point
            (4, 1) coordinate (y3), % y3 point
        };

    \addplot [
        draw=gray!50,
        dashed,
        ] coordinates {
            (1, 2) -| (0, 2) -| (0, 0) -| (1, 0); % top left to bottom left to bottom to top left dashed line
            (1, 2) -| (1, 0) -| (2, 0) -| (2, 2); % top right to bottom right to bottom to top right dashed line
        };

    \fill [
        pattern=north east lines,
        pattern color=red!20,
    ] (2, 4) rectangle (5, 5); % shading top right region

    \node at (x) [above left] {$x$}; % label x point
    \node at (y1) [above right] {$y_1$}; % label y1 point
    \node at (y2) [right] {$y_2$}; % label y2 point
    \node at (y3) [below right] {$y_3$}; % label y3 point

\end{axis}
\end{tikzpicture}

\end{document}
```

